-- Generated by scripts/generate-food-seed.mjs from supabase/seed/*.json.
-- Do not edit by hand: change the JSON and generate a new migration.
-- 40 starter recipes (needs the catalog foods for suggested sides).

insert into public.recipes (slug, title_en, title_fa, category, servings,
  steps_en, steps_fa, tip_en, tip_fa, tags, suggested_side_food_id, suggested_side_grams)
select v.slug, v.title_en, v.title_fa, v.category, v.servings, v.steps_en, v.steps_fa,
  v.tip_en, v.tip_fa, v.tags, f.id, v.side_grams
from (values
('starter-b01', 'Bread, feta, walnut & herbs', 'نان، پنیر، گردو و سبزی', 'breakfast', 1, array['Weigh the bread or cut off the stated amount.','Cut the cheese to about the size of a matchbox.','Wash the herbs and arrange them with the tomato and cucumber next to the bread.','Have your tea without sugar, or with one date.']::text[], array['نان را وزن کنید یا به اندازه گفته‌شده جدا کنید.','پنیر را به اندازه یک قوطی کبریت ببرید.','سبزی را بشویید و با گوجه و خیار کنار نان بچینید.','چای را بدون قند یا با یک خرما میل کنید.']::text[], 'Buy low-fat, low-salt cheese. Keep walnuts to 2 halves at most; they are high in calories.', 'پنیر کم‌چرب و کم‌نمک بخرید. گردو را بیشتر از ۲ مغز نکنید؛ کالری بالایی دارد.', array['quick']::text[], null, null),
('starter-b02', 'Tomato omelette', 'املت گوجه‌فرنگی', 'breakfast', 1, array['Finely chop the onion and sauté it in a non-stick pan with the oil for 2 minutes.','Peel and chop the tomatoes, add them and cook until most of the liquid is gone (about 8 minutes).','Add the spices, crack in the eggs and stir until set.','Serve with bread and herbs.']::text[], array['پیاز را ریز خرد کنید و با روغن در تابه نچسب ۲ دقیقه تفت دهید.','گوجه‌ها را پوست بگیرید، خرد کنید و اضافه کنید تا آبش کم شود (حدود ۸ دقیقه).','ادویه را بزنید، تخم‌مرغ‌ها را بشکنید و هم بزنید تا ببندد.','با نان و سبزی سرو کنید.']::text[], 'In a non-stick pan, one teaspoon of oil is enough.', 'با تابه نچسب، یک قاشق چای‌خوری روغن کافی است.', array['quick']::text[], null, null),
('starter-b03', 'Oat porridge with apple & cinnamon', 'فرنی جو دوسر با سیب و دارچین', 'breakfast', 1, array['Put the oats and milk in a small pot over low heat.','Stir constantly for 5 minutes until thick.','Add the apple and cinnamon and cook for 1 more minute.','Sprinkle the chopped walnuts on top.']::text[], array['جو دوسر و شیر را در قابلمه کوچک روی حرارت ملایم بگذارید.','مدام هم بزنید تا ۵ دقیقه غلیظ شود.','سیب و دارچین را اضافه کنید و ۱ دقیقه دیگر بپزید.','گردوی خرد شده را روی آن بریزید.']::text[], 'Don''t add sugar or honey; the apple is sweet enough.', 'شکر یا عسل اضافه نکنید؛ شیرینی سیب کافی است.', array['quick']::text[], null, null),
('starter-b04', 'Fried eggs with sangak & herbs', 'نیمرو با نان سنگک و سبزی', 'breakfast', 1, array['Heat a non-stick pan with a little oil.','Crack in the eggs and cover the pan so the tops set.','Serve with bread, tomato, cucumber and herbs.']::text[], array['تابه نچسب را با کمی روغن گرم کنید.','تخم‌مرغ‌ها را بشکنید، درِ تابه را بگذارید تا روی آن ببندد.','با نان، گوجه، خیار و سبزی سرو کنید.']::text[], 'You can cook the yolk through; it makes no difference to the calories.', 'زرده را می‌توان کامل پخت؛ تفاوتی در کالری ندارد.', array['quick']::text[], null, null),
('starter-b05', 'Yogurt, oat & pomegranate bowl', 'کاسه ماست، جو دوسر و انار', 'breakfast', 1, array['Put the yogurt in a bowl.','Add the oats on top (raw, or lightly toasted in a dry pan).','Add the pomegranate, walnuts and honey.']::text[], array['ماست را در کاسه بریزید.','جو دوسر (خام یا کمی تفت‌داده در تابه خشک) را روی آن بریزید.','انار، گردو و عسل را اضافه کنید.']::text[], 'Out of season, use apple or strawberries instead of pomegranate.', 'در فصل‌های دیگر به جای انار سیب یا توت‌فرنگی بگذارید.', array['quick']::text[], null, null),
('starter-b06', 'Lentil breakfast stew', 'عدسی', 'breakfast', 4, array['Soak the lentils overnight and drain them in the morning.','Chop the onion, fry it in the oil until golden and add the turmeric.','Add the lentils, diced potato and 4 cups of water.','Simmer on low heat for 40 minutes until thick.','Finish with a little salt and golpar. Serve with lemon juice.']::text[], array['عدس را از شب قبل خیس کنید و صبح آبکش کنید.','پیاز را خرد کنید و با روغن طلایی کنید، زردچوبه بزنید.','عدس و سیب‌زمینی خرد شده و ۴ لیوان آب اضافه کنید.','با حرارت ملایم ۴۰ دقیقه بپزید تا لعاب بیندازد.','در پایان نمک کم و گلپر بزنید. با آبلیمو سرو کنید.']::text[], 'Legumes: only if your doctor allows them. One portion = one bowl (a quarter of the pot).', 'حبوبات: فقط اگر پزشک اجازه داد. یک سهم = یک کاسه (یک چهارم قابلمه).', array['legume','batch']::text[], 'ing-sangak', 50),
('starter-b07', 'Oat & banana pancakes', 'پنکیک جو دوسر و موز', 'breakfast', 1, array['Grind the oats to a powder in a blender.','Add the banana, egg, milk and cinnamon and blend.','Grease a non-stick pan with a little oil and pour 2 spoonfuls of batter per pancake.','Cook for 2 minutes on each side. Serve with one teaspoon of honey.']::text[], array['جو دوسر را در مخلوط‌کن پودر کنید.','موز، تخم‌مرغ، شیر و دارچین را اضافه کنید و مخلوط کنید.','تابه نچسب را با کمی روغن چرب کنید و برای هر پنکیک ۲ قاشق مایه بریزید.','هر طرف ۲ دقیقه بپزید. با یک قاشق چای‌خوری عسل سرو کنید.']::text[], 'A weekend breakfast; makes about 4 small pancakes.', 'برای روزهای تعطیل؛ حدود ۴ پنکیک کوچک می‌شود.', '{}'::text[], null, null),
('starter-m01', 'Barberry rice with chicken', 'زرشک پلو با مرغ', 'rice', 4, array['Put the chicken in a pot with the sliced onion, turmeric, a little salt and half a cup of water.','Simmer on low heat for 40 minutes. Add the tomato paste and half the saffron and cook 10 more minutes until the sauce thickens.','Wash the barberries and sauté them with one teaspoon of oil and a little saffron for just 30 seconds (they burn quickly).','Cook the rice separately. Weigh your portion, top it with the barberries and put the chicken beside it.']::text[], array['مرغ را با پیاز حلقه شده، زردچوبه، نمک کم و نصف لیوان آب در قابلمه بگذارید.','با حرارت ملایم ۴۰ دقیقه بپزید. رب و نصف زعفران را اضافه کنید و ۱۰ دقیقه دیگر بپزید تا سس غلیظ شود.','زرشک را بشویید و با یک قاشق چای‌خوری روغن و کمی زعفران فقط ۳۰ ثانیه تفت دهید (زود می‌سوزد).','برنج را جدا بپزید. سهم کیارش را وزن کنید، زرشک را رویش بریزید و مرغ را کنارش بگذارید.']::text[], 'Don''t add sugar to the barberries. Always remove the chicken skin.', 'شکر به زرشک اضافه نکنید. پوست مرغ را حتماً جدا کنید.', array['batch']::text[], 'ing-chelo', 180),
('starter-m02', 'Light ghormeh sabzi', 'خورش قورمه سبزی سبک', 'rice', 4, array['Soak the beans overnight, changing the water a few times.','Sauté the onion in one spoon of oil, then add the meat and turmeric until the meat changes colour.','Add the beans and 4 cups of water and simmer for 1 hour.','Fry the herbs in one spoon of oil in a non-stick pan (little oil, low heat and patience).','Add the herbs and the pierced dried limes and cook 1 more hour. Add salt at the end.']::text[], array['لوبیا را از شب قبل خیس کنید و آبش را چند بار عوض کنید.','پیاز را با یک قاشق روغن تفت دهید، گوشت و زردچوبه را اضافه کنید تا رنگ گوشت عوض شود.','لوبیا و ۴ لیوان آب را اضافه کنید و ۱ ساعت با حرارت ملایم بپزید.','سبزی را با یک قاشق روغن در تابه نچسب سرخ کنید (کم روغن، با حرارت ملایم و صبر).','سبزی و لیموعمانی سوراخ‌شده را اضافه کنید و ۱ ساعت دیگر بپزید. نمک را آخر بزنید.']::text[], 'You can fry a big batch of herbs and freeze it. Skim the oil off the top of the stew before serving.', 'سبزی را می‌شود یکجا سرخ و فریز کرد. روغن سطح خورش را پیش از سرو با قاشق بگیرید.', array['red_meat','legume','batch']::text[], 'ing-chelo', 180),
('starter-m03', 'Light gheymeh', 'خورش قیمه سبک', 'rice', 4, array['Soak the split peas for 2 hours.','Sauté the onion in the oil, then add the meat and turmeric.','Add the tomato paste and fry for 2 minutes. Add the split peas, 3 cups of water and the dried limes.','Simmer for 1½ hours until the split peas are soft but not mushy.','Cut the potato into thin sticks, toss with one teaspoon of oil and a little salt, and bake at 200 °C for 25 minutes.']::text[], array['لپه را ۲ ساعت خیس کنید.','پیاز را با روغن تفت دهید، گوشت و زردچوبه را اضافه کنید.','رب را اضافه کنید و ۲ دقیقه تفت دهید. لپه و ۳ لیوان آب و لیمو عمانی را اضافه کنید.','۱ ساعت و نیم با حرارت ملایم بپزید تا لپه نرم شود ولی له نشود.','سیب‌زمینی را خلالی کنید، با یک قاشق چای‌خوری روغن و نمک کم هم بزنید و در فر ۲۰۰ درجه ۲۵ دقیقه بپزید.']::text[], 'Deep-fried potatoes double the calories of the stew; the oven or an air fryer is better.', 'سیب‌زمینی سرخ‌کرده در روغن زیاد کالری خورش را دو برابر می‌کند؛ فر یا سرخ‌کن بدون روغن بهتر است.', array['red_meat','legume','batch']::text[], 'ing-chelo', 180),
('starter-m04', 'Celery stew with chicken', 'خورش کرفس با مرغ', 'rice', 4, array['Sauté the onion in half the oil, then add the chicken and turmeric.','Add 2 cups of water and cook for 30 minutes.','Sauté the celery in the rest of the oil for 5 minutes, then add the parsley and mint and sauté 5 more minutes.','Add the celery and herbs to the chicken and cook for 45 minutes. Add the lemon juice, saffron and salt in the last 10 minutes.']::text[], array['پیاز را با نصف روغن تفت دهید، مرغ و زردچوبه را اضافه کنید.','۲ لیوان آب اضافه کنید و ۳۰ دقیقه بپزید.','کرفس را با بقیه روغن ۵ دقیقه تفت دهید، سپس جعفری و نعناع را اضافه کنید و ۵ دقیقه دیگر تفت دهید.','کرفس و سبزی را به مرغ اضافه کنید و ۴۵ دقیقه بپزید. آبلیمو، زعفران و نمک را در ۱۰ دقیقه آخر بزنید.']::text[], 'You can use chicken breast instead of thigh; cut the cooking time by 15 minutes.', 'به جای ران می‌توان از سینه مرغ استفاده کرد؛ زمان پخت را ۱۵ دقیقه کم کنید.', array['batch']::text[], 'ing-chelo', 180),
('starter-m05', 'Spinach & prune stew with chicken', 'خورش آلو اسفناج با مرغ', 'rice', 4, array['Sauté the onion in the oil, then add the chicken and turmeric.','Add 2 cups of water and cook for 30 minutes.','Put the chopped spinach in a dry pan (no oil) until its water cooks off.','Add the spinach and prunes to the stew and cook 30 more minutes. Adjust sourness and salt at the end.']::text[], array['پیاز را با روغن تفت دهید، مرغ و زردچوبه را اضافه کنید.','۲ لیوان آب اضافه کنید و ۳۰ دقیقه بپزید.','اسفناج خرد شده را در تابه خشک (بدون روغن) بریزید تا آبش کشیده شود.','اسفناج و آلوها را به خورش اضافه کنید و ۳۰ دقیقه دیگر بپزید. ترشی و نمک را آخر تنظیم کنید.']::text[], 'Frozen spinach works well too.', 'اسفناج یخ‌زده هم خوب است.', array['batch']::text[], 'ing-chelo', 180),
('starter-m06', 'Eggplant stew with chicken (oven eggplant)', 'خورش بادمجان با مرغ (بادمجان تنوری)', 'rice', 4, array['Peel the eggplants, slice them lengthwise, salt lightly and leave for 20 minutes to draw out the bitterness.','Pat the eggplants dry, brush them with one tablespoon of oil and bake at 200 °C for 25 minutes.','Sauté the onion in the rest of the oil, add the chicken, turmeric and tomato paste, then pour in 2 cups of water and cook for 30 minutes.','Arrange the eggplant and tomato slices over the chicken, add the verjuice and simmer for 30 minutes.']::text[], array['بادمجان‌ها را پوست بگیرید، طولی برش بزنید، کمی نمک بزنید و ۲۰ دقیقه بگذارید تلخی‌اش برود.','بادمجان‌ها را خشک کنید، با برس یک قاشق غذاخوری روغن به آن‌ها بزنید و در فر ۲۰۰ درجه ۲۵ دقیقه بپزید.','پیاز را با بقیه روغن تفت دهید، مرغ، زردچوبه و رب را اضافه کنید، سپس ۲ لیوان آب بریزید و ۳۰ دقیقه بپزید.','بادمجان و گوجه‌های حلقه شده را روی مرغ بچینید، آبغوره بریزید و ۳۰ دقیقه با حرارت ملایم بپزید.']::text[], 'Fried eggplant soaks up to 4 times more oil; use the oven instead.', 'بادمجان سرخ‌کرده تا ۴ برابر روغن جذب می‌کند؛ فر را جایگزین کنید.', array['batch']::text[], 'ing-chelo', 180),
('starter-m07', 'Light fesenjan with chicken', 'فسنجان سبک با مرغ', 'rice', 4, array['Toast the walnuts in a dry pan for 3 minutes, put them in a pot with 3 cups of water and cook for 1 hour until they release their oil.','Sauté the onion in the oil and add the chicken pieces until they change colour.','Add the chicken and pomegranate molasses to the walnuts and cook 45 more minutes.','Adjust the taste with a little cinnamon and salt.']::text[], array['گردو را در تابه خشک ۳ دقیقه تفت دهید، با ۳ لیوان آب در قابلمه بریزید و ۱ ساعت بپزید تا روغن بیندازد.','پیاز را با روغن تفت دهید، مرغ تکه شده را اضافه کنید تا رنگش عوض شود.','مرغ و رب انار را به گردو اضافه کنید و ۴۵ دقیقه دیگر بپزید.','مزه را با کمی دارچین و نمک تنظیم کنید.']::text[], 'The highest-calorie dish in this collection; twice a month at most, with less rice.', 'پرکالری‌ترین غذای این کتاب است؛ حداکثر ماهی دو بار و با برنج کمتر.', array['treat']::text[], 'ing-chelo', 150),
('starter-m08', 'Green bean rice with chicken', 'لوبیا پلو با مرغ', 'rice', 4, array['Sauté the onion in the oil and add the chicken until it changes colour.','Add the green beans and sauté for 5 minutes. Add the tomato paste and spices.','Pour in half a cup of water and cook for 15 minutes until the beans are half done.','Drain the parboiled rice, layer it with the mixture in the pot and steam on low heat for 45 minutes.']::text[], array['پیاز را با روغن تفت دهید، مرغ را اضافه کنید تا رنگش عوض شود.','لوبیا سبز را اضافه کنید و ۵ دقیقه تفت دهید. رب و ادویه را اضافه کنید.','نصف لیوان آب بریزید و ۱۵ دقیقه بپزید تا لوبیا نیم‌پز شود.','برنج را آبکش کنید، لایه‌لایه با مواد در قابلمه بریزید و ۴۵ دقیقه با حرارت ملایم دم کنید.']::text[], 'One portion = a quarter of the pot (about 350 g). Skip the tahdig, or make it with thin lavash bread.', 'یک سهم = یک چهارم قابلمه (حدود ۳۵۰ گرم). ته‌دیگ را حذف کنید یا با نان لواش نازک درست کنید.', array['batch','one_pot']::text[], null, null),
('starter-m09', 'Lentil rice', 'عدس پلو', 'rice', 4, array['Cook the lentils for 20 minutes until half done.','Parboil the rice and drain it together with the lentils.','Slice the onion thinly and fry it until golden in one spoon of oil over low heat.','Sauté the raisins with the onion for 30 seconds.','Steam the rice and lentils and top with the fried onion and raisins.']::text[], array['عدس را ۲۰ دقیقه بپزید تا نیم‌پز شود.','برنج را نیم‌پز و با عدس آبکش کنید.','پیاز را نازک خلال کنید و با یک قاشق روغن و حرارت ملایم طلایی کنید.','کشمش را ۳۰ ثانیه با پیاز تفت دهید.','برنج و عدس را دم کنید و پیاز داغ و کشمش را رویش بریزید.']::text[], 'Meat-free; good for days when you have already had more protein. Legumes only with your doctor''s approval.', 'بدون گوشت است؛ برای روزهایی که پروتئین بیشتری خورده‌اید مناسب است. حبوبات فقط با اجازه پزشک.', array['legume','batch','one_pot','low_protein']::text[], 'ing-yogurt-low', 150),
('starter-m10', 'Shirazi cabbage rice with chicken meatballs', 'کلم پلو شیرازی با قلقلی مرغ', 'rice', 4, array['Knead the minced chicken with half the onion (grated and squeezed dry) and a little salt, and shape small meatballs.','Brown the meatballs in a non-stick pan with one teaspoon of oil.','Chop the rest of the onion and sauté it with the shredded cabbage and the rest of the oil for 10 minutes. Add the herbs.','Layer the parboiled rice with the cabbage and meatballs in the pot and steam for 45 minutes.']::text[], array['مرغ چرخ‌کرده را با نصف پیاز رنده و آبگیری شده و کمی نمک ورز دهید و قلقلی‌های کوچک درست کنید.','قلقلی‌ها را در تابه نچسب با یک قاشق چای‌خوری روغن طلایی کنید.','بقیه پیاز را خرد کنید و با کلم خرد شده و بقیه روغن ۱۰ دقیقه تفت دهید. سبزی را اضافه کنید.','برنج نیم‌پز را با کلم و قلقلی لایه‌لایه در قابلمه بریزید و ۴۵ دقیقه دم کنید.']::text[], 'Dried herbs work too (use a quarter of the amount).', 'سبزی خشک هم می‌شود (یک چهارم مقدار).', array['batch','one_pot']::text[], null, null),
('starter-m11', 'Tomato rice with chicken & potato', 'استانبولی پلو با مرغ', 'rice', 4, array['Sauté the onion in the oil and add the diced chicken.','Add the potato, tomato paste and grated tomato and cook for 10 minutes.','Add the soaked rice and 2 cups of water.','When the water is absorbed, cover the pot with a steaming lid and cook on low heat for 40 minutes.']::text[], array['پیاز را با روغن تفت دهید، مرغ مکعبی را اضافه کنید.','سیب‌زمینی، رب و گوجه رنده‌شده را اضافه کنید و ۱۰ دقیقه بپزید.','برنج خیس‌خورده و ۲ لیوان آب را اضافه کنید.','وقتی آب کشیده شد، درِ قابلمه را دم‌کنی بگذارید و ۴۰ دقیقه با حرارت ملایم بپزید.']::text[], 'One portion = a quarter of the pot. Great with Shirazi salad.', 'یک سهم = یک چهارم قابلمه. با سالاد شیرازی عالی است.', array['batch','one_pot']::text[], null, null),
('starter-m12', 'Quince & prune stew with chicken', 'خورش به و آلو با مرغ', 'rice', 4, array['Sauté the onion in half the oil, add the chicken, pour in 2 cups of water and cook for 30 minutes.','Cut the quince into wedges without peeling and sauté in the rest of the oil for 5 minutes.','Add the quince, prunes, saffron and lemon juice to the chicken and cook for 45 minutes until the quince is soft and pink.']::text[], array['پیاز را با نصف روغن تفت دهید، مرغ را اضافه کنید، ۲ لیوان آب بریزید و ۳۰ دقیقه بپزید.','به را بدون پوست قاچ کنید و با بقیه روغن ۵ دقیقه تفت دهید.','به، آلو، زعفران و آبلیمو را به مرغ اضافه کنید و ۴۵ دقیقه بپزید تا به نرم و صورتی شود.']::text[], 'An autumn and winter dish. Don''t add sugar.', 'غذای فصل پاییز و زمستان. شکر اضافه نکنید.', array['batch','seasonal']::text[], 'ing-chelo', 180),
('starter-n01', 'Saffron chicken kebab', 'جوجه کباب زعفرانی (فر یا منقل)', 'main', 4, array['Cube the chicken and marinate it in the fridge with grated onion, yogurt, lemon juice, oil, saffron and a little salt for at least 4 hours (overnight is better).','Thread onto skewers or spread on an oven tray.','Cook in the oven at 220 °C for 20–25 minutes, or over a grill.','Grill the tomatoes and peppers alongside.']::text[], array['مرغ را مکعبی کنید و با پیاز رنده، ماست، آبلیمو، روغن، زعفران و کمی نمک حداقل ۴ ساعت (بهتر یک شب) در یخچال بخوابانید.','به سیخ بکشید یا در سینی فر بچینید.','در فر ۲۲۰ درجه ۲۰ تا ۲۵ دقیقه یا روی منقل بپزید.','گوجه و فلفل را کنارش کباب کنید.']::text[], 'One portion is 90 g of raw chicken (about 5 pieces).', 'سهم کیارش ۹۰ گرم مرغ خام است (حدود ۵ تکه).', array['batch']::text[], 'ing-chelo', 150),
('starter-n02', 'Light pan kebab', 'کباب تابه‌ای سبک', 'main', 4, array['Knead the meat, squeezed onion, turmeric and pepper for 10 minutes until sticky.','Spread it in a greased non-stick pan and score lines with the back of a spoon.','Cover and cook on medium heat for 10 minutes; pour off any extra liquid.','Cut into pieces, turn over and cook 5 more minutes. Cook the tomatoes in the same pan.']::text[], array['گوشت، پیاز آبگیری شده، زردچوبه و فلفل را ۱۰ دقیقه ورز دهید تا چسبناک شود.','در تابه نچسب چرب‌شده پهن کنید و با پشت قاشق خط بیندازید.','درب را بگذارید و ۱۰ دقیقه با حرارت متوسط بپزید؛ آب اضافه را خالی کنید.','برش بزنید، برگردانید و ۵ دقیقه دیگر بپزید. گوجه‌ها را در همان تابه بپزید.']::text[], 'Red meat: twice a week at most.', 'گوشت قرمز: حداکثر هفته‌ای دو بار.', array['red_meat']::text[], 'ing-chelo', 150),
('starter-n03', 'Oven-baked stuffed trout', 'ماهی قزل‌آلای شکم‌پر تنوری', 'main', 4, array['Wash the fish and season it inside and out with a little salt, pepper and lemon juice.','Sauté the onion in half the oil, add the herbs, barberries, walnuts and pomegranate molasses and sauté for 5 minutes.','Stuff the fish with the filling and close it with toothpicks.','Place it on a lined oven tray, brush with the rest of the oil and bake at 200 °C for 25 minutes.']::text[], array['ماهی را بشویید، داخل و بیرونش را کمی نمک، فلفل و آبلیمو بزنید.','پیاز را با نصف روغن تفت دهید، سبزی، زرشک، گردو و رب انار را اضافه کنید و ۵ دقیقه تفت دهید.','شکم ماهی را با مواد پر کنید و با خلال دندان ببندید.','روی سینی فر با کاغذ روغنی بگذارید، روی ماهی بقیه روغن را با برس بزنید و در فر ۲۰۰ درجه ۲۵ دقیقه بپزید.']::text[], 'Fish once a week is enough. Avoid kilka, sardines and smoked fish.', 'ماهی: هفته‌ای یک بار کافی است. از کیلکا، ساردین و ماهی دودی پرهیز کنید.', array['fish']::text[], 'ing-chelo', 150),
('starter-n04', 'Oven kuku sabzi', 'کوکو سبزی تنوری', 'main', 4, array['Chop the herbs and dry them thoroughly.','Beat the eggs with the spices and flour, then add the herbs, walnuts and barberries.','Grease an oven dish with oil, pour in the mixture and brush a little oil on top.','Bake at 180 °C for 35 minutes. Cut into 4 pieces.']::text[], array['سبزی را خرد و کاملاً خشک کنید.','تخم‌مرغ‌ها را با ادویه و آرد هم بزنید، سبزی، گردو و زرشک را اضافه کنید.','قالب فر را با روغن چرب کنید، مایه را بریزید و روی آن کمی روغن بزنید.','در فر ۱۸۰ درجه ۳۵ دقیقه بپزید. به ۴ قسمت برش بزنید.']::text[], 'Oven kuku needs half the oil of a pan and cooks more evenly. It is tasty cold too.', 'کوکو در فر نصف روغن تابه را می‌خواهد و یکدست‌تر می‌پزد. سرد هم خوشمزه است.', array['batch']::text[], 'ing-sangak', 70),
('starter-n05', 'Oven potato kuku', 'کوکو سیب‌زمینی تنوری', 'main', 4, array['Boil, peel and grate the potatoes.','Mix with the eggs, squeezed onion and spices.','Spread in a greased oven tray, or shape small patties by hand and arrange them on baking paper.','Bake at 200 °C for 30 minutes, turning halfway.']::text[], array['سیب‌زمینی‌ها را آب‌پز و پوست بگیرید و رنده کنید.','با تخم‌مرغ، پیاز آبگیری شده و ادویه مخلوط کنید.','در سینی فر چرب‌شده پهن کنید یا با دست کتلت‌های کوچک شکل دهید و روی کاغذ روغنی بچینید.','در فر ۲۰۰ درجه ۳۰ دقیقه بپزید؛ وسط پخت برگردانید.']::text[], 'Serve with Shirazi salad and pickles.', 'با سالاد شیرازی و خیارشور سرو کنید.', array['batch','low_protein']::text[], 'ing-sangak', 60),
('starter-n06', 'Mirza ghasemi', 'میرزا قاسمی', 'main', 4, array['Roast the eggplants over a gas flame or in the oven, peel and chop finely.','Sauté the garlic in the oil for 30 seconds, add the turmeric and eggplant and sauté for 5 minutes.','Add the grated tomato and cook for 10 minutes until the liquid is gone.','Add the eggs and stir until set.']::text[], array['بادمجان‌ها را روی شعله گاز یا در فر کباب کنید، پوست بگیرید و ریز خرد کنید.','سیر را با روغن ۳۰ ثانیه تفت دهید، زردچوبه و بادمجان را اضافه کنید و ۵ دقیقه تفت دهید.','گوجه رنده‌شده را اضافه کنید و ۱۰ دقیقه بپزید تا آبش کشیده شود.','تخم‌مرغ‌ها را اضافه کنید و هم بزنید تا ببندد.']::text[], 'A light, filling dinner; great for evenings.', 'شام سبک و پرحجم؛ برای شب‌ها عالی است.', array['low_protein']::text[], 'ing-sangak', 80),
('starter-n07', 'Light kashk-e bademjan', 'کشک بادمجان سبک', 'main', 4, array['Peel the eggplants, brush with a little oil and bake at 200 °C for 30 minutes.','Fry the onion in one spoon of oil, adding the garlic and turmeric at the end.','Mash the eggplant and cook it with half the fried onion and half a cup of water for 10 minutes.','Add the kashk and stir for 5 minutes. Garnish with the rest of the fried onion, mint oil and walnuts.']::text[], array['بادمجان‌ها را پوست بگیرید، با برس کمی روغن بزنید و در فر ۲۰۰ درجه ۳۰ دقیقه بپزید.','پیاز را با یک قاشق روغن داغ کنید، سیر و زردچوبه را آخر اضافه کنید.','بادمجان را له کنید، با نصف پیاز داغ و نصف لیوان آب ۱۰ دقیقه بپزید.','کشک را اضافه کنید و ۵ دقیقه هم بزنید. با بقیه پیاز داغ، نعناع داغ و گردو تزئین کنید.']::text[], 'Kashk is salty; don''t add salt to this dish.', 'کشک شور است؛ به این غذا نمک اضافه نکنید.', array['low_protein']::text[], 'ing-sangak', 80),
('starter-n08', 'Stuffed peppers with chicken', 'دلمه فلفل دلمه‌ای با مرغ', 'main', 4, array['Parboil the rice for 10 minutes.','Sauté the onion in the oil, add the minced chicken and turmeric until it changes colour.','Add the rice, herbs and half the tomato paste.','Cut the tops off the peppers, remove the seeds and fill them.','Stand them in a pot, mix the rest of the paste with a cup of water and the lemon juice, and pour over. Simmer for 45 minutes.']::text[], array['برنج را ۱۰ دقیقه نیم‌پز کنید.','پیاز را با روغن تفت دهید، مرغ چرخ‌کرده و زردچوبه را اضافه کنید تا رنگش عوض شود.','برنج، سبزی و نصف رب را اضافه کنید.','سر فلفل‌ها را ببرید، تخمه‌ها را خالی کنید و پر کنید.','در قابلمه بچینید، بقیه رب را با یک لیوان آب و آبلیمو مخلوط کنید و رویشان بریزید. ۴۵ دقیقه با حرارت ملایم بپزید.']::text[], 'One portion = one pepper. If you''re still hungry, another half pepper is fine.', 'یک سهم = یک فلفل. اگر سیر نشدید، نصف فلفل دیگر هم اشکالی ندارد.', array['batch']::text[], 'ing-yogurt-low', 100),
('starter-n09', 'Light chicken tahchin', 'ته‌چین مرغ سبک', 'main', 4, array['Parboil and drain the rice.','Beat the yogurt, egg, saffron and a little salt, and mix with half the rice.','Grease the bottom of a non-stick pot, add half the yogurt rice, lay the chicken on it and cover with the rest of the rice.','Cook on low heat for 1 hour, or in the oven at 180 °C for 1½ hours. Sprinkle the barberries on top.']::text[], array['برنج را نیم‌پز و آبکش کنید.','ماست، تخم‌مرغ، زعفران و کمی نمک را هم بزنید و با نصف برنج مخلوط کنید.','ته قابلمه نچسب را با روغن چرب کنید، نصف برنج ماستی را بریزید، مرغ را بچینید، بقیه برنج را رویش بریزید.','۱ ساعت با حرارت ملایم یا ۱ ساعت و نیم در فر ۱۸۰ درجه بپزید. زرشک را رویش بریزید.']::text[], 'One portion = a quarter of the dish.', 'یک سهم = یک چهارم قالب.', array['batch']::text[], null, null),
('starter-n10', 'Oven-baked kotlet', 'کتلت تنوری', 'main', 4, array['Knead all the ingredients except the breadcrumbs and oil.','Shape oval patties (about 12) and coat them lightly in breadcrumbs.','Arrange on a lined oven tray and brush with oil.','Bake at 200 °C for 25 minutes, turning halfway.']::text[], array['همه مواد به جز پودر سوخاری و روغن را ورز دهید.','کتلت‌های بیضی شکل بدهید (حدود ۱۲ عدد) و کمی پودر سوخاری بزنید.','روی سینی فر با کاغذ روغنی بچینید و با برس روغن بزنید.','در فر ۲۰۰ درجه ۲۵ دقیقه بپزید؛ وسط پخت برگردانید.']::text[], 'One portion = 3 patties. Good cold for a packed lunch too.', 'یک سهم = ۳ کتلت. سرد هم برای ناهار دانشگاه خوب است.', array['red_meat','batch']::text[], 'ing-lavash', 50),
('starter-n11', 'Yatimcheh (eggplant & tomato)', 'یتیمچه', 'main', 4, array['Cube the eggplants, brush with oil and bake at 200 °C for 20 minutes.','Sauté the onion in a little oil, then add the garlic, turmeric and tomato paste.','Add the diced tomatoes and cook for 10 minutes.','Add the eggplant and simmer for 20 minutes.']::text[], array['بادمجان‌ها را مکعبی کنید، با برس روغن بزنید و در فر ۲۰۰ درجه ۲۰ دقیقه بپزید.','پیاز را با کمی روغن تفت دهید، سیر، زردچوبه و رب را اضافه کنید.','گوجه‌های مکعبی را اضافه کنید و ۱۰ دقیقه بپزید.','بادمجان را اضافه کنید و ۲۰ دقیقه با حرارت ملایم بپزید.']::text[], 'Meat-free; for low-protein days. Serve with kateh rice or bread.', 'بدون گوشت؛ برای روزهای کم‌پروتئین. با کته یا نان سرو کنید.', array['low_protein']::text[], 'ing-chelo', 150),
('starter-n12', 'Oven chicken & vegetable tray', 'خوراک مرغ و سبزیجات تنوری', 'main', 4, array['Cut all the vegetables into large pieces.','Mix the chicken and vegetables with the oil, garlic, lemon juice and spices in a large bowl.','Spread on an oven tray (not on top of each other).','Bake at 200 °C for 40 minutes, stirring once.']::text[], array['همه سبزیجات را درشت خرد کنید.','مرغ و سبزیجات را با روغن، سیر، آبلیمو و ادویه در یک کاسه بزرگ مخلوط کنید.','در سینی فر پهن کنید (روی هم نباشند).','در فر ۲۰۰ درجه ۴۰ دقیقه بپزید؛ یک بار هم بزنید.']::text[], 'A complete meal on one tray; great for busy days.', 'یک غذای کامل در یک سینی؛ برای روزهای شلوغ عالی است.', array['batch','one_pot']::text[], null, null),
('starter-n13', 'Light olivieh salad', 'سالاد الویه سبک', 'main', 4, array['Boil the chicken, potatoes, eggs and carrot.','Grate or finely chop everything, then add the pickles and peas.','Mix the yogurt with the olive oil, lemon juice, one teaspoon of mustard, salt and pepper.','Combine the dressing with the rest and chill for 1 hour.']::text[], array['مرغ، سیب‌زمینی، تخم‌مرغ و هویج را آب‌پز کنید.','همه را رنده یا ریز خرد کنید، خیارشور و نخود فرنگی را اضافه کنید.','ماست را با روغن زیتون، آبلیمو، یک قاشق چای‌خوری خردل، نمک و فلفل هم بزنید.','سس را با مواد مخلوط کنید و ۱ ساعت در یخچال بگذارید.']::text[], 'A yogurt dressing instead of mayonnaise cuts the calories by more than half. One portion = a quarter of the bowl, with lettuce or one lavash bread.', 'سس ماستی به جای مایونز کالری را بیش از نصف کم می‌کند. یک سهم = یک چهارم ظرف، با کاهو یا یک نان لواش.', array['batch']::text[], null, null),
('starter-s01', 'Barley soup with chicken', 'سوپ جو با مرغ', 'soup', 4, array['Soak the barley for 2 hours.','Sauté the onion in the oil, then add the chicken and tomato paste.','Add the barley and 6 cups of water and cook for 1 hour.','Shred the chicken and return it, add the grated carrot and cook for 20 minutes.','Add the parsley and lemon juice at the end.']::text[], array['جو را ۲ ساعت خیس کنید.','پیاز را با روغن تفت دهید، مرغ و رب را اضافه کنید.','جو و ۶ لیوان آب را اضافه کنید و ۱ ساعت بپزید.','مرغ را ریش‌ریش کنید و برگردانید، هویج رنده را اضافه کنید و ۲۰ دقیقه بپزید.','جعفری و آبلیمو را آخر اضافه کنید.']::text[], 'One portion = one large bowl. Soup before a meal reduces appetite.', 'یک سهم = یک کاسه بزرگ. سوپ قبل از غذا اشتها را کم می‌کند.', array['batch']::text[], 'ing-sangak', 40),
('starter-s02', 'Light ash reshteh', 'آش رشته سبک', 'soup', 4, array['Soak the legumes overnight and cook them in 8 cups of water for 1 hour.','Add the chopped herbs and spinach and cook for 45 minutes.','Add the noodles and stir for 15 minutes.','Make the fried onion and mint oil with as little oil as possible.','Serve each bowl with one spoon of kashk.']::text[], array['حبوبات را از شب قبل خیس کنید و با ۸ لیوان آب ۱ ساعت بپزید.','سبزی و اسفناج خرد شده را اضافه کنید و ۴۵ دقیقه بپزید.','رشته را اضافه کنید و ۱۵ دقیقه هم بزنید.','پیاز داغ و نعناع داغ را با کمترین روغن درست کنید.','با یک قاشق کشک در هر کاسه سرو کنید.']::text[], 'Legumes only with your doctor''s approval. Kashk is salty; don''t add salt to the ash.', 'حبوبات فقط با اجازه پزشک. کشک شور است؛ به آش نمک نزنید.', array['legume','batch']::text[], null, null),
('starter-s03', 'Vegetable soup', 'سوپ سبزیجات', 'soup', 4, array['Sauté the onion in the oil and add the diced chicken.','Add all the diced vegetables and the grated tomato.','Add 6 cups of water and cook for 45 minutes.','Add the parsley and lemon juice at the end.']::text[], array['پیاز را با روغن تفت دهید، مرغ مکعبی را اضافه کنید.','همه سبزیجات مکعبی و گوجه رنده‌شده را اضافه کنید.','۶ لیوان آب اضافه کنید و ۴۵ دقیقه بپزید.','جعفری و آبلیمو را آخر اضافه کنید.']::text[], 'The lowest-calorie dish in the collection; for hungry evenings or before a main meal.', 'کم‌کالری‌ترین غذای کتاب؛ برای شب‌های گرسنگی یا قبل از غذای اصلی.', array['batch','low_protein']::text[], null, null),
('starter-s04', 'Onion eshkeneh', 'اشکنه پیاز', 'soup', 4, array['Slice the onion thinly and fry it in the oil over low heat until golden.','Add the flour, turmeric and mint and fry for 1 minute.','Add the diced potato and 5 cups of water and cook for 30 minutes.','Crack the eggs into the soup one at a time and let them set without stirring.']::text[], array['پیاز را نازک خلال کنید و با روغن و حرارت ملایم طلایی کنید.','آرد، زردچوبه و نعناع را اضافه کنید و ۱ دقیقه تفت دهید.','سیب‌زمینی مکعبی و ۵ لیوان آب را اضافه کنید و ۳۰ دقیقه بپزید.','تخم‌مرغ‌ها را یکی‌یکی داخل آش بشکنید و بدون هم زدن بگذارید ببندد.']::text[], 'A traditional, inexpensive dish for cold nights.', 'غذای سنتی و ارزان برای شب‌های سرد.', array['low_protein']::text[], 'ing-sangak', 60),
('starter-k01', 'Shirazi salad', 'سالاد شیرازی', 'side', 4, array['Finely dice the cucumber, tomato and onion.','Add the lemon juice, olive oil, mint and a little salt.','Toss just before serving.']::text[], array['خیار، گوجه و پیاز را ریز خرد کنید.','آبلیمو، روغن زیتون، نعناع و کمی نمک را اضافه کنید.','قبل از سرو هم بزنید.']::text[], 'Alongside any lunch or dinner; adds volume with almost no calories.', 'کنار هر ناهار و شام؛ حجم می‌دهد و تقریباً کالری ندارد.', array['quick']::text[], null, null),
('starter-k02', 'Mast-o khiar', 'ماست و خیار', 'side', 4, array['Finely dice the cucumber.','Mix with the yogurt, mint and dried rose petals.','Top with the walnuts and raisins.']::text[], array['خیار را ریز خرد کنید.','با ماست، نعناع و گل‌محمدی مخلوط کنید.','گردو و کشمش را رویش بریزید.']::text[], 'Low-fat dairy is a good choice for people watching uric acid.', 'لبنیات کم‌چرب برای اسید اوریک مفید است.', array['quick']::text[], null, null),
('starter-k03', 'Spinach borani', 'بورانی اسفناج', 'side', 4, array['Cook the spinach in a dry pan until its water is gone, then let it cool.','Sauté the onion and garlic in the oil.','Mix the spinach, fried onion and yogurt.']::text[], array['اسفناج را در تابه خشک بپزید تا آبش کشیده شود و خنک کنید.','پیاز و سیر را با روغن تفت دهید.','اسفناج، پیاز داغ و ماست را مخلوط کنید.']::text[], 'Serve alongside kuku or kebab.', 'کنار کوکو یا کباب.', array['quick']::text[], null, null),
('starter-k04', 'Night bowl: yogurt, apple & cinnamon', 'کاسه شبانه: ماست، سیب و دارچین', 'snack', 1, array['Chop the apple.','Mix with the yogurt and cinnamon and top with the walnuts.']::text[], array['سیب را خرد کنید.','با ماست و دارچین مخلوط کنید و گردو را رویش بریزید.']::text[], 'Instead of late-night cake and biscuits. If you are still hungry afterwards: vegetable soup.', 'جایگزین کیک و بیسکویت آخر شب. اگر بعد از این هم گرسنه بودید: سوپ سبزیجات.', array['quick','night']::text[], null, null)
) as v(slug, title_en, title_fa, category, servings, steps_en, steps_fa, tip_en, tip_fa, tags, side_slug, side_grams)
left join public.foods f on f.slug = v.side_slug
on conflict (slug) do update set
  title_en = excluded.title_en, title_fa = excluded.title_fa, category = excluded.category,
  servings = excluded.servings, steps_en = excluded.steps_en, steps_fa = excluded.steps_fa,
  tip_en = excluded.tip_en, tip_fa = excluded.tip_fa, tags = excluded.tags,
  suggested_side_food_id = excluded.suggested_side_food_id,
  suggested_side_grams = excluded.suggested_side_grams;
